package com.rpms.app;
import com.rpms.dao.*;import com.rpms.model.*;import com.rpms.service.*;import com.rpms.util.*;import java.math.BigDecimal;import java.time.LocalDate;import java.sql.SQLException;
public class RecruitmentApp {
 private static final CandidateService candidates=new CandidateService();private static final JobService jobs=new JobService();
 private static final CompanyDAO companies=new CompanyDAO();private static final JobDAO jobDao=new JobDAO();private static final WorkflowDAO workflow=new WorkflowDAO();private static final ReportDAO reports=new ReportDAO();
 public static void main(String[] args){
  System.out.println("RECRUITMENT & PLACEMENT MANAGEMENT SYSTEM");
  while(true){try{
   System.out.println("\n1. Candidates\n2. Companies\n3. Jobs\n4. Applications\n5. Interviews\n6. Offers\n7. Placements\n8. Reports\n9. Exit");
   int choice=ConsoleInput.integer("Select: ");
   switch(choice){case 1->candidateMenu();case 2->companyMenu();case 3->jobMenu();case 4->applicationMenu();case 5->interviewMenu();case 6->offerMenu();case 7->placementMenu();case 8->reports.menu();case 9->{System.out.println("Goodbye.");return;}default->System.out.println("Invalid option.");}
  }catch(Exception e){System.out.println("ERROR: "+e.getMessage());}}
 }
 private static void candidateMenu()throws Exception{
  System.out.println("1 Add  2 View All  3 Deactivate  4 Update");int x=ConsoleInput.integer("Select: ");
  if(x==1){String code=ConsoleInput.text("Candidate code: "),name=ConsoleInput.text("Full name: "),email=ConsoleInput.text("Email: "),mobile=ConsoleInput.text("10-digit mobile: "),qual=ConsoleInput.text("Qualification: "),college=ConsoleInput.text("College: "),uni=ConsoleInput.text("University: ");int year=ConsoleInput.integer("Passing year: ");double pct=ConsoleInput.decimal("Percentage: ").doubleValue();int back=ConsoleInput.integer("Backlogs: ");String tech=ConsoleInput.text("Primary technology: "),loc=ConsoleInput.text("Current location: ");candidates.add(new Candidate(0,code,name,email,mobile,qual,college,uni,year,pct,back,tech,loc,"ACTIVE"));System.out.println("Candidate added.");}
  else if(x==2){for(Candidate c:candidates.all())System.out.printf("%d | %s | %s | %s | %.2f%% | %s%n",c.id,c.code,c.name,c.technology,c.percentage,c.status);}
  else if(x==3){candidates.deactivate(ConsoleInput.integer("Candidate ID: "));System.out.println("Candidate deactivated.");}
  else if(x==4){int id=ConsoleInput.integer("Candidate ID: ");String name=ConsoleInput.text("Full name: "),email=ConsoleInput.text("Email: "),mobile=ConsoleInput.text("Mobile: "),qual=ConsoleInput.text("Qualification: "),college=ConsoleInput.text("College: "),uni=ConsoleInput.text("University: ");int year=ConsoleInput.integer("Passing year: ");double pct=ConsoleInput.decimal("Percentage: ").doubleValue();int back=ConsoleInput.integer("Backlogs: ");String tech=ConsoleInput.text("Primary technology: "),loc=ConsoleInput.text("Current location: "),status=ConsoleInput.text("Profile status ACTIVE/INACTIVE/ON_HOLD: ").toUpperCase();candidates.update(new Candidate(id,"",name,email,mobile,qual,college,uni,year,pct,back,tech,loc,status));System.out.println("Candidate updated.");}
 }
 private static void companyMenu()throws Exception{System.out.println("1 Add  2 View All");int x=ConsoleInput.integer("Select: ");if(x==1){companies.add(ConsoleInput.text("Company code: "),ConsoleInput.text("Company name: "),ConsoleInput.text("Industry: "),ConsoleInput.text("Location: "),ConsoleInput.text("HR name: "),ConsoleInput.text("HR email: "));ActivityLogger.log("Company Created");System.out.println("Company added.");}else companies.list();}
 private static void jobMenu()throws Exception{System.out.println("1 Create Job  2 View Jobs");int x=ConsoleInput.integer("Select: ");if(x==1){int co=ConsoleInput.integer("Company ID: ");String code=ConsoleInput.text("Job code: "),title=ConsoleInput.text("Job title: "),tech=ConsoleInput.text("Technology (use skill master if maintained): "),loc=ConsoleInput.text("Location: ");int openings=ConsoleInput.integer("Openings: ");BigDecimal min=ConsoleInput.decimal("Minimum package LPA (0 if none): "),max=ConsoleInput.decimal("Maximum package LPA (0 if none): "),pct=ConsoleInput.decimal("Minimum percentage: ");int minY=ConsoleInput.integer("Minimum passing year (0 if none): "),maxY=ConsoleInput.integer("Maximum passing year (0 if none): "),back=ConsoleInput.integer("Maximum backlogs: ");LocalDate posted=ConsoleInput.date("Posted date YYYY-MM-DD: "),deadline=ConsoleInput.date("Deadline YYYY-MM-DD: ");Job j=new Job(0,co,code,title,tech,loc,openings,min.signum()==0?null:min,max.signum()==0?null:max,pct,minY,maxY,back,posted,deadline,"OPEN");jobs.add(j);System.out.println("Job created.");}else jobDao.list();}
 private static void applicationMenu()throws Exception{System.out.println("1 Apply for Job (eligibility check)  2 View Applications  3 Change Status");int x=ConsoleInput.integer("Select: ");if(x==1){workflow.apply(ConsoleInput.integer("Candidate ID: "),ConsoleInput.integer("Job ID: "),ConsoleInput.text("Source (Portal/Recruiter/Referral): "));System.out.println("Application created. Candidate is eligible.");}else if(x==2)workflow.listApplications();else if(x==3){int id=ConsoleInput.integer("Application ID: ");String s=ConsoleInput.text("Next status: ").toUpperCase();workflow.changeStatus(id,s,ConsoleInput.text("Remarks: "));System.out.println("Status updated.");}}
 private static void interviewMenu()throws Exception{System.out.println("1 Schedule Interview  2 Add Feedback");int x=ConsoleInput.integer("Select: ");if(x==1){workflow.scheduleInterview(ConsoleInput.integer("Application ID (must be SHORTLISTED): "),ConsoleInput.integer("Round number: "),ConsoleInput.text("Round type (APTITUDE/TECHNICAL/MANAGERIAL/HR): ").toUpperCase(),ConsoleInput.date("Date YYYY-MM-DD: "),ConsoleInput.text("Mode (ONLINE/OFFLINE/TELEPHONIC): ").toUpperCase(),ConsoleInput.text("Interviewer: "));System.out.println("Interview scheduled.");}else if(x==2){workflow.addFeedback(ConsoleInput.integer("Interview ID: "),ConsoleInput.decimal("Technical rating: ").doubleValue(),ConsoleInput.decimal("Communication rating: ").doubleValue(),ConsoleInput.decimal("Problem-solving rating: ").doubleValue(),ConsoleInput.decimal("Overall rating: ").doubleValue(),ConsoleInput.text("Recommendation NEXT_ROUND/SELECTED/REJECTED/ON_HOLD: ").toUpperCase(),ConsoleInput.text("Remarks: "));System.out.println("Feedback saved.");}}
 private static void offerMenu()throws Exception{System.out.println("1 Create Offer (application must be SELECTED)  2 Update Offer Status");int x=ConsoleInput.integer("Select: ");if(x==1){workflow.createOffer(ConsoleInput.integer("Application ID: "),ConsoleInput.text("Designation: "),ConsoleInput.decimal("Package LPA: "),ConsoleInput.date("Offer date YYYY-MM-DD: "),ConsoleInput.date("Expected joining date YYYY-MM-DD: "));System.out.println("Offer created.");}else if(x==2){workflow.updateOfferStatus(ConsoleInput.integer("Offer ID: "),ConsoleInput.text("Status OFFERED/ACCEPTED/REJECTED/EXPIRED/WITHDRAWN: ").toUpperCase());System.out.println("Offer status updated.");}}
 private static void placementMenu()throws Exception{System.out.println("1 Confirm Joining (offer must be ACCEPTED)");if(ConsoleInput.integer("Select: ")==1){workflow.confirmJoining(ConsoleInput.integer("Offer ID: "),ConsoleInput.date("Actual joining date YYYY-MM-DD: "));System.out.println("Placement confirmed.");}}
}
